# Standard library
import uuid
from datetime import datetime

# Third-party
from sqlalchemy import DateTime, Integer, JSON, Real, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, TimestampMixin


class ExplorerSubGeoPerformance(TimestampMixin, Base):
    __tablename__ = "explorer_sub_geo_performance"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid()."
        ),
    )
    started_at: Mapped[datetime | None] = mapped_column(
        DateTime(timezone=True),
        description=(
            "Timezone-aware UTC timestamp of when the activity began "
            "recording."
        ),
    )
    ended_at: Mapped[datetime | None] = mapped_column(
        DateTime(timezone=True),
        description=(
            "Timezone-aware UTC timestamp of when the activity finished "
            "recording."
        ),
    )
    total_time_s: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Total elapsed wall-clock time of the activity in seconds, "
            "including all stops and pauses."
        ),
    )
    moving_time_s: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Time in seconds during which the user was actively moving, "
            "excluding stops and pauses."
        ),
    )
    stop_time_s: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Time in seconds the user spent stationary during the activity "
            "(rest breaks, pauses)."
        ),
    )
    moving_ratio: Mapped[float | None] = mapped_column(
        Real,
        description=(
            "Fraction of total time spent moving (moving_time_s / "
            "total_time_s), ranging from 0.0 to 1.0."
        ),
    )
    avg_speed_kmh: Mapped[float | None] = mapped_column(
        Real,
        description=(
            "Overall average speed in km/h computed over the entire activity "
            "duration including stops."
        ),
    )
    moving_avg_speed_kmh: Mapped[float | None] = mapped_column(
        Real,
        description=(
            "Average speed in km/h computed only over moving time, excluding "
            "stationary periods."
        ),
    )
    ascent_avg_speed_kmh: Mapped[float | None] = mapped_column(
        Real,
        description=(
            "Average speed in km/h during uphill (ascending) sections of the "
            "activity."
        ),
    )
    descent_avg_speed_kmh: Mapped[float | None] = mapped_column(
        Real,
        description=(
            "Average speed in km/h during downhill (descending) sections of "
            "the activity."
        ),
    )
    max_speed_kmh: Mapped[float | None] = mapped_column(
        Real,
        description=(
            "Peak instantaneous speed in km/h recorded at any point during "
            "the activity."
        ),
    )
    max_ascent_speed_kmh: Mapped[float | None] = mapped_column(
        Real,
        description=(
            "Peak instantaneous speed in km/h recorded during an uphill "
            "(ascending) section."
        ),
    )
    max_descent_speed_kmh: Mapped[float | None] = mapped_column(
        Real,
        description=(
            "Peak instantaneous speed in km/h recorded during a downhill "
            "(descending) section."
        ),
    )
    avg_heart_rate: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Average heart rate in beats per minute over the entire activity."
        ),
    )
    max_heart_rate: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Maximum heart rate in beats per minute recorded during the "
            "activity."
        ),
    )
    min_heart_rate: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Minimum heart rate in beats per minute recorded during the "
            "activity."
        ),
    )
    calories_burned: Mapped[int | None] = mapped_column(
        Integer,
        description="Estimated total calories burned during the activity.",
    )
    steps_count: Mapped[int | None] = mapped_column(
        Integer,
        description=(
            "Total step count recorded during the activity, if available from "
            "the tracking device."
        ),
    )
    heart_graph: Mapped[dict | None] = mapped_column(
        JSON,
        description=(
            "JSONB data representing heart rate over time, used to render the "
            "heart rate graph in the UI."
        ),
    )
    speed_pattern: Mapped[dict | None] = mapped_column(
        JSON,
        description=(
            "JSONB data representing speed variations over time or distance, "
            "used for pace analysis visualization."
        ),
    )
